1	export interface Card {
2	  monster: string;
3	  rank?: number;
4	}
5	
6	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
7	
8	const TYPE_THRESHOLD = 3;
9	const POINTS_PER_SPHINX = 1;
10	const POINTS_WITHIN_THRESHOLD = 1;
11	const POINTS_PER_TYPE_BEYOND_THRESHOLD = 2;
12	
13	const distinctTypesSeenBySphinx = (army: Card[]): number =>
14	  new Set(army.filter((card) => !isSphinx(card)).map((card) => card.monster))
15	    .size;
16	
17	const varietyPoints = (typeCount: number): number =>
18	  typeCount > TYPE_THRESHOLD
19	    ? POINTS_PER_TYPE_BEYOND_THRESHOLD * (typeCount - TYPE_THRESHOLD)
20	    : POINTS_WITHIN_THRESHOLD;
21	
22	const scoreOneSphinx = (typeCount: number): number =>
23	  POINTS_PER_SPHINX + varietyPoints(typeCount);
24	
25	export const scoreArmy = (army: Card[]): number => {
26	  const sphinxCount = army.filter(isSphinx).length;
27	  return sphinxCount * scoreOneSphinx(distinctTypesSeenBySphinx(army));
28	};
